using System;

var stats = Analyze(new[] { 4, 8, 15 });
Console.WriteLine(stats.Min);
Console.WriteLine(stats.Max);
Console.WriteLine(stats.Count);

(int Min, int Max, int Count) Analyze(int[] numbers)
{
    var min = numbers[0];
    var max = numbers[0];
    var count = 0;
    foreach (var n in numbers)
    {
        if (n < min) min = n;
        if (n > max) max = n;
        count++;
    }
    return (min, max, count);
}

